function main(): void {
  const S = Symbol('s');
  const o: any = Object.defineProperties({ a: 1 }, { [S]: { value: 7 }, ['x' + 'y']: { value: 8 } });
  console.log(o[S], o.xy, Object.keys(o).join(), Object.getOwnPropertySymbols(o).length);
  const c: any = Object.assign({}, o);
  console.log(c.xy, Object.keys(c).join());
  console.log(JSON.stringify(o));
}
